// All markers are filled in one pass, so a value can never fill another one, and
// the replacement function keeps $& and similar patterns literal.
const fill=(config:string,enrollment:string,portalRoot:string)=>template.replace(/__(CONFIG|ENROLLMENT|PORTAL_ROOT)_JSON__/g,(_marker,name:string)=>name==="CONFIG"?config:name==="ENROLLMENT"?enrollment:portalRoot);
// JSON inside a PowerShell single-quoted string: ' is doubled, and non-ASCII is
// written as JSON escapes, because PowerShell also ends such a string at typographic quotes.
const quoted=(value:unknown)=>JSON.stringify(value).replace(/[^\x20-\x7e]/g,character=>"\\u"+character.charCodeAt(0).toString(16).padStart(4,"0")).replaceAll("'","''");
// The portal's own root certificate (base64 DER, lib/server/agent/portal-certificate.ts), or null without one.
const portalRootJson=(portalRoot?:string)=>portalRoot?quoted({certificate:portalRoot}):"null";
export function installerV3(c:Registration,portalRoot?:string) { return fill(quoted({...c,mode:c.mode??"ReadOnly"}),"null",portalRootJson(portalRoot)); }
export function registrationV3(c:Registration) { return JSON.stringify({...c,mode:c.mode??"ReadOnly"},null,2)+"\n"; }
/** The customer installer: no registration yet; the script enrolls with these credentials first. */
export function customerInstallerV3(c:{origin:string;installerKey:string},portalRoot?:string) { return fill("null",quoted({origin:c.origin,installerKey:c.installerKey}),portalRootJson(portalRoot)); }
